function validate([n, edges]) {
  if (!Number.isInteger(n) || n < 1 || n > 20000) return 'n is an integer from 1 to 2 * 10^4.';
  if (!Array.isArray(edges) || edges.length < n - 1 || edges.length > 40000) return 'edges needs between n - 1 and 4 * 10^4 edges.';
  const parent = Array.from({ length: n + 1 }, (_, i) => i);
  const find = (x) => { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; };
  const seen = new Set();
  let parts = n;
  for (const e of edges) {
    if (!Array.isArray(e) || e.length !== 3 || !e.every(Number.isInteger)) return 'Each edge is [u, v, weight] with integers.';
    const [u, v, w] = e;
    if (u < 1 || u > n || v < 1 || v > n || u === v) return 'Edge endpoints are two different nodes from 1 to n.';
    if (w < 1 || w > 100000) return 'Each weight is from 1 to 10^5.';
    const key = Math.min(u, v) * 100000 + Math.max(u, v);
    if (seen.has(key)) return 'At most one edge may join two nodes.';
    seen.add(key);
    const a = find(u), b = find(v);
    if (a !== b) { parent[a] = b; parts--; }
  }
  if (parts !== 1) return 'The graph must be connected.';
  return null;
}

