function countRestrictedPaths(n, edges) {
  const dist = new Array(n + 1).fill(Infinity);
  dist[n] = 0;
  for (let round = 0; round < n; round++) {
    for (const [u, v, w] of edges) {
      if (dist[u] + w < dist[v]) dist[v] = dist[u] + w;
      if (dist[v] + w < dist[u]) dist[u] = dist[v] + w;
    }
  }
  const memo = new Map();
  const count = (node) => {
    if (node === n) return 1;
    if (memo.has(node)) return memo.get(node);
    let total = 0;
    for (const [u, v] of edges) {
      const other = u === node ? v : v === node ? u : 0;
      if (other !== 0 && dist[other] < dist[node]) total = (total + count(other)) % 1000000007;
    }
    memo.set(node, total);
    return total;
  };
  return count(1);
}

