function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? int(700, 1000) : int(1, 7);
  const maxWeight = large ? (rand() < 0.5 ? 3 : 100000) : (rand() < 0.7 ? 3 : 20);
  const labels = Array.from({ length: n }, (_, i) => i + 1);
  for (let i = n - 1; i > 0; i--) {
    const j = int(0, i);
    [labels[i], labels[j]] = [labels[j], labels[i]];
  }
  const edges = [];
  const used = new Set();
  const add = (u, v) => {
    const key = Math.min(u, v) * 100000 + Math.max(u, v);
    if (u === v || used.has(key)) return;
    used.add(key);
    edges.push([u, v, int(1, maxWeight)]);
  };
  for (let i = 1; i < n; i++) add(labels[i], labels[int(0, i - 1)]);
  const pairs = n * (n - 1) / 2;
  const target = Math.min(pairs, large ? 2000 : n - 1 + int(0, 2 * n));
  let tries = 0;
  while (edges.length < target && tries++ < 100000) add(int(1, n), int(1, n));
  return [n, edges];
}
